export type CallerSuppliedDeliveryOutcomeRequest = ({ "amount_money"?: MoneyValue; /** RFC3339 timestamp. Format: date-time. */ "expires_at"?: string; /** Why Flint could not calculate the method and the action that can make calculation succeed. - `dependency_failure`: Retry after the dependent service recovers. - `timeout`: Retry after the timed-out dependency recovers. - `malformed_response`: Fix the callback response so it matches the documented response schema, then retry. - `callback_transport_failure`: Restore callback DNS, TLS, network connectivity, and response timing, then retry. - `callback_result_invalid`: Fix the callback result fields or values identified by the callback logs, then retry. - `pricing_failure`: Fix the method pricing configuration or matching rate, then retry. - `schedule_failure`: Fix the method schedule, timezone, or requested window, then retry. - `geography_failure`: Fix the destination, origin, or geographic configuration, then retry. - `routing_failure`: Fix inventory routing or origin assignment, then retry. - `address_verification_failed`: Correct the address fields rejected by verification, then retry. - `address_could_not_be_verified`: Confirm or correct the address, or retry when address verification is available. */ "failure_category"?: "dependency_failure" | "timeout" | "malformed_response" | "callback_transport_failure" | "callback_result_invalid" | "pricing_failure" | "schedule_failure" | "geography_failure" | "routing_failure" | "address_verification_failed" | "address_could_not_be_verified" | (string & {}); /** maxLength: 500. */ "merchant_reference"?: string; "offered_windows"?: Array<DeliveryWindowRequest>; "retryable"?: boolean; /** RFC3339 timestamp. Format: date-time. */ "selection_guarantee_expires_at"?: string; "service_level"?: string; "type": "available" | "unavailable" | "cannot_calculate" | (string & {}); /** Why the method is unavailable and the action that can make it eligible. - `destination_not_served`: Use a destination covered by this method or choose another method. - `pickup_unavailable`: Choose an available pickup method or location. - `no_window_available`: Choose another offered window or a method with availability for the requested time. - `eligibility_no_match`: Inspect eligibility_mismatches, then change the relevant buyer facts or method eligibility rule. - `pricing_unavailable`: Add or activate a matching rate, or provide the required caller-supplied price. - `inventory_unavailable`: Choose an origin or method backed by available inventory. */ "unavailable_reason"?: "destination_not_served" | "pickup_unavailable" | "no_window_available" | "eligibility_no_match" | "pricing_unavailable" | "inventory_unavailable" | (string & {}); /** RFC3339 timestamp. Format: date-time. */ "window_end_at"?: string; /** RFC3339 timestamp. Format: date-time. */ "window_start_at"?: string; }) & (({ "type": "available"; "amount_money": unknown; "expires_at": unknown; "selection_guarantee_expires_at": unknown; }) | ({ "type": "unavailable"; "unavailable_reason": unknown; }) | ({ "type": "cannot_calculate"; "failure_category": unknown; "retryable": unknown; }) | (object));
